# Spring Boot host config. H2 in-memory in the same JVM; Flyway migrates the schema up on boot from
# db/migration; Actuator health is the readiness probe.

# In-memory H2 (dies with the JVM = clean per-run reset).
spring.datasource.url=jdbc:h2:mem:officehq;DB_CLOSE_DELAY=-1
spring.datasource.driver-class-name=org.h2.Driver
spring.datasource.username=sa
spring.datasource.password=
# Pooled connections are never retired: when HikariCP closes one at its default 30 min
# max-lifetime, this in-memory H2 closes under the remaining sessions and every later statement
# fails with "The database has been closed" while the health probe stays UP. 0 means no lifetime.
spring.datasource.hikari.max-lifetime=0

# Flyway owns the schema. JPA does not create tables.
spring.flyway.enabled=true
spring.jpa.hibernate.ddl-auto=none
# Close the persistence context at the end of the request, not during view rendering.
spring.jpa.open-in-view=false

# Readiness probe.
management.endpoints.web.exposure.include=health
management.endpoint.health.probes.enabled=true

# The SPA is served from src/main/resources/static (built there by bin/build); deep-link
# fallback is in SpaConfig.java.

# Audit sink: one record per line to this known file, so tests assert side-effects by reading it.
# bin/start passes an absolute path via AUDIT_FILE; default is .run/audit.log.
app.audit.file=${AUDIT_FILE:.run/audit.log}
-- A person's claims on a sheet, listed newest first (by id). The amount is 0.00 or more, in two
-- decimals; claim_date defaults to the sheet's today when the claim is made.
CREATE TABLE claim (
    id         BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id   VARCHAR(255)   NOT NULL,
    person_id  BIGINT         NOT NULL REFERENCES person (id),
    amount     DECIMAL(15, 2) NOT NULL CHECK (amount >= 0),
    claim_date DATE           NOT NULL,
    note       VARCHAR(4000)  NOT NULL
);
CREATE INDEX claim_sheet ON claim (sheet_id, id);
-- A claim's number becomes text: the sheet-wide 1, 2, ... or, while the sheet numbers by period, <period>-<n>
-- (X-<n> for a claim in no period). A correction names the number it corrects the same way.
-- claim_period_number_seq holds the last number each sheet gave in each period ('' is the no-period sequence).
ALTER TABLE claim ALTER COLUMN claim_number SET DATA TYPE VARCHAR(300);
ALTER TABLE claim ALTER COLUMN corrects SET DATA TYPE VARCHAR(300);
CREATE TABLE claim_period_number_seq (
    sheet_id    VARCHAR(255) NOT NULL,
    scope       VARCHAR(255) NOT NULL,
    last_number BIGINT       NOT NULL,
    PRIMARY KEY (sheet_id, scope)
);
-- A claim bound by its person's last statement: stated, at the figure it had then (stated_due; null when it
-- had none). It shows and totals that figure until the person's next statement, which rebinds every claim
-- of theirs that counts then and leaves the rest unbound.
ALTER TABLE claim ADD COLUMN stated BOOLEAN DEFAULT FALSE NOT NULL;
ALTER TABLE claim ADD COLUMN stated_due DECIMAL(15, 2);

-- The statements taken of a person, in the order taken (by id): their due-total then ("n/a" when it had
-- none), how many of their claims counted, and the sheet's today when it was taken.
CREATE TABLE statement (
    id         BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id   VARCHAR(255) NOT NULL,
    person_id  BIGINT       NOT NULL REFERENCES person (id),
    due_total  VARCHAR(32)  NOT NULL,
    claims     INT          NOT NULL,
    stated_on  DATE         NOT NULL
);
CREATE INDEX statement_sheet ON statement (sheet_id, person_id, id);
import { useState } from 'react';
import { useQuery } from '@tanstack/react-query';
import { ClaimCells } from '../../slots/defs/claimColumns';
import { PersonCells, PersonHeaders } from '../../slots/defs/personColumns';
import { claimsQuery } from './claimsQuery';
import { ClaimForm } from './ClaimForm';

/** A person's claims, newest first, with the form they are added and edited through. */
function PersonClaims({ sheetId, personId }: { sheetId: string; personId: number }) {
  const claims = (useQuery(claimsQuery(sheetId)).data ?? []).filter((c) => c.personId === personId);
  const [editingId, setEditingId] = useState<number | undefined>();
  const editing = claims.find((c) => c.id === editingId);

  return (
    <td data-testid="person-claims">
      <table>
        <tbody>
          {claims.map((c) => (
            <tr key={c.id} data-testid={`claim-row-${c.id}`}>
              <td data-testid="claim-number">{c.number ?? ''}</td>
              <td data-testid="claim-amount">{c.amount}</td>
              <td data-testid="claim-date">{c.date}</td>
              <td data-testid="claim-note">{c.note}</td>
              <td data-testid="claim-corrects">{c.corrects ?? ''}</td>
              <ClaimCells.Slot sheetId={sheetId} claim={c} />
              <td>
                {c.id === editing?.id ? (
                  <button type="button" data-testid="claim-cancel" onClick={() => setEditingId(undefined)}>
                    Cancel
                  </button>
                ) : (
                  <button type="button" data-testid="claim-edit" onClick={() => setEditingId(c.id)}>
                    Edit
                  </button>
                )}
              </td>
            </tr>
          ))}
        </tbody>
      </table>
      <ClaimForm sheetId={sheetId} personId={personId} editing={editing} onDone={() => setEditingId(undefined)} />
    </td>
  );
}

export const contributions = [
  PersonHeaders.fill({ order: 20, Component: () => <th>Claims</th> }),
  PersonCells.fill({ order: 20, Component: PersonClaims }),
];
import { getJson } from '../../api/http';
import type { Person } from '../people/peopleQuery';
import { sheetKey } from '../sheet/sheetQuery';

export type ClaimStatus = 'DRAFT' | 'OPEN' | 'PENDING' | 'SETTLED' | 'VOID';

/** An open claim: OPEN, or PENDING (settled by a clerk above the clerk limit, awaiting a steward), handled like OPEN in every total. */
export const isOpen = (c: Claim) => c.status === 'OPEN' || c.status === 'PENDING';

/**
 * `amount` has two decimals ("12.50"); `date` is yyyy-mm-dd; `number` is given on opening and kept when voided (null for a draft);
 * `settledDue` is the due fixed on settling (null when not settled, or settled while no rate applied on the claim's date);
 * `openedBy` is the user who opened it (null when never opened), who cannot settle it;
 * `stated` is whether its person's last statement bound it, at `statedDue` (null when it had no figure then) — a PENDING claim is not bound while PENDING;
 * a negative `amount` is a correction, and `corrects` is the number of the settled claim it corrects (null for any other claim).
 */
export type Claim = {
  id: number;
  personId: number;
  amount: string;
  date: string;
  note: string;
  status: ClaimStatus;
  number: string | null;
  settledDue: string | null;
  openedBy: string | null;
  stated: boolean;
  statedDue: string | null;
  corrects: string | null;
};

/** A correction: its due is its amount times the rate, with no floor and no late charge. */
export const isCorrection = (c: Claim) => Number(c.amount) < 0;

/**
 * Only open (OPEN or PENDING) and SETTLED claims count toward claimed, due and every total; drafts and voided
 * ones do not, nor do the open claims of a person on hold.
 */
export const counts = (c: Claim, people: Person[]) =>
  c.status === 'SETTLED' || (isOpen(c) && !people.find((p) => p.id === c.personId)?.held);

/** Under the sheet's key, so re-loading the sheet re-reads its claims. */
export const claimsKey = (sheetId: string) => [...sheetKey(sheetId), 'claims'] as const;

/** Every claim on the sheet, newest first. */
export const claimsQuery = (sheetId: string) => ({
  queryKey: claimsKey(sheetId),
  queryFn: () => getJson<Claim[]>(`/api/sheets/${encodeURIComponent(sheetId)}/claims`),
});

/** Amounts are added up in whole cents, so the sum shows exactly with two decimals. */
export function sumAmounts(claims: Claim[]): string {
  const cents = claims.reduce((total, c) => total + Math.round(Number(c.amount) * 100), 0);
  return (cents / 100).toFixed(2);
}
import { useState } from 'react';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { putJson, RefusedError } from '../../api/http';
import { ClaimCells } from '../../slots/defs/claimColumns';
import { useSubmitOnce } from '../../api/useSubmitOnce';
import { useUser } from '../session/useUser';
import { claimsKey } from './claimsQuery';
import type { Claim, ClaimStatus } from './claimsQuery';

type Decision = 'approve' | 'reject';

const ACTIONS: Array<{ action: string; to: ClaimStatus; label: string; decision?: Decision }> = [
  { action: 'open', to: 'OPEN', label: 'Open' },
  { action: 'settle', to: 'SETTLED', label: 'Settle' },
  { action: 'void', to: 'VOID', label: 'Void' },
  { action: 'approve', to: 'SETTLED', label: 'Approve', decision: 'approve' },
];

/**
 * A claim's status and the buttons that change it. Every button is offered; the server refuses a
 * change the status does not allow, a settle by the user who opened the claim, a clerk's settle of a claim
 * whose due is above the sheet's clerk limit, or any change to a claim dated in a closed period, and the refusal
 * shows on the claim until its next action. A clerk's settle above the clerk limit makes the claim PENDING: a
 * steward other than its opener approves it (SETTLED) or rejects it with a reason (back to OPEN).
 */
function ClaimStatusCell({ sheetId, claim }: { sheetId: string; claim: Claim }) {
  const queryClient = useQueryClient();
  const [user] = useUser();
  const [error, setError] = useState('');
  const [reason, setReason] = useState('');
  const once = useSubmitOnce();
  const change = useMutation({
    mutationFn: ({ to, decision, reason }: { to: ClaimStatus; decision?: Decision; reason?: string }) =>
      putJson<Claim>(
        `/api/sheets/${encodeURIComponent(sheetId)}/claims/${claim.id}/status/${to}`,
        { action: decision, reason },
        user,
      ),
    onSuccess: () => queryClient.invalidateQueries({ queryKey: claimsKey(sheetId) }),
    onError: (e, { to, decision, reason }) =>
      setError(
        e instanceof RefusedError
          ? e.message
          : (decision !== undefined) !== (claim.status === 'PENDING') && to !== 'VOID'
            ? decision !== undefined
              ? `Only a PENDING claim can be ${decision === 'approve' ? 'approved' : 'rejected'}.`
              : 'A PENDING claim is approved or rejected by a steward, or voided.'
            : to === 'SETTLED' && claim.openedBy === user
              ? `The user who opened a claim cannot ${decision === 'approve' ? 'approve' : 'settle'} it.`
              : decision === 'reject' && !reason?.trim()
                ? 'Give a reason to reject the claim.'
                : decision !== undefined
                  ? 'Only a steward can approve or reject a pending claim.'
                  : `A ${claim.status} claim cannot become ${to}.`,
      ),
  });

  return (
    <td>
      <span data-testid="claim-status">{claim.status}</span>{' '}
      {ACTIONS.map(({ action, to, label, decision }) => (
        <button
          key={action}
          type="button"
          data-testid={`claim-${action}`}
          disabled={change.isPending}
          onClick={() => {
            setError('');
            once(() => change.mutateAsync({ to, decision }));
          }}
        >
          {label}
        </button>
      ))}
      <input
        data-testid="claim-reject-reason"
        placeholder="Reason"
        value={reason}
        onChange={(e) => {
          setReason(e.target.value);
          setError('');
        }}
      />
      <button
        type="button"
        data-testid="claim-reject"
        disabled={change.isPending}
        onClick={() => {
          setError('');
          once(() => change.mutateAsync({ to: 'OPEN', decision: 'reject', reason }).then(() => setReason('')));
        }}
      >
        Reject
      </button>
      {error && <span data-testid="claim-error">{error}</span>}
    </td>
  );
}

export const contribution = ClaimCells.fill({ order: 20, Component: ClaimStatusCell });
import { defineSlot } from '../Slot';
import type { Claim } from '../../features/claims/claimsQuery';

/**
 * A person's claims table, column by column. A feature that shows something per claim contributes
 * a <td>, rendered in each claim's row after its own cells.
 */
export const ClaimCells = defineSlot<{ sheetId: string; claim: Claim }>('claim.cells');

